/**
 * The admin console's frame: a platform admin only (404 otherwise, with no
 * audit row — each page records its own visit), its own sidebar from
 * `@/lib/admin-nav`, outside the app shell. Every page and every action
 * still authorizes itself: a layout does not guard a page's reads or a
 * server action.
 */

import { getTranslations } from "next-intl/server";
import type { ReactNode } from "react";

import { AdminSidebar } from "@/components/admin/admin-sidebar";
import { ShellHeader } from "@/components/shell/shell-header";
import { TimeZoneCookie } from "@/components/shell/time-zone-cookie";
import { AISidebarInset, AISidebarProvider } from "@/components/ui/ai-sidebar";
import { adminConfig } from "@/lib/admin-config";
import { adminLayoutGate } from "@/lib/admin-page";

export const dynamic = "force-dynamic";

export async function generateMetadata() {
  const t = await getTranslations("admin-console");
  return { title: t("meta.title"), robots: { index: false } };
}

export default async function AdminLayout({
  children,
}: {
  children: ReactNode;
}) {
  await adminLayoutGate();
  const t = await getTranslations();

  return (
    <AISidebarProvider className="h-svh min-h-0 overflow-hidden">
      {/* Renders nothing; tells the server which day it is here. */}
      <TimeZoneCookie />
      <AdminSidebar
        brand={t(adminConfig.brandKey)}
        backHref={adminConfig.backHref}
      />
      <AISidebarInset className="min-h-0 overflow-hidden">
        <ShellHeader />
        <div className="min-h-0 min-w-0 flex-1 space-y-6 overflow-y-auto px-4 py-6 md:px-8 md:py-8">
          {children}
        </div>
      </AISidebarInset>
    </AISidebarProvider>
  );
}

/**
 * The console's overview: the product's own panels first
 * (`adminConfig.overviewPanels`), then the platform's — the last 24 hours,
 * the newest workspaces and integration health — so every deployment shows
 * the same operational truth.
 *
 * Each read renders on its own: one that fails says so, and the rest of
 * the page still renders.
 */

import {
  getIntegrationHealth,
  getPlatformOverview,
  listUnsettledExecutions,
  listWorkspaces,
} from "@intelligo-dev/admin";
import { getTranslations } from "next-intl/server";

import { IntegrationHealth } from "@/components/admin/integration-health";
import { PageTitle } from "@/components/admin/page-title";
import { PlatformOverview } from "@/components/admin/platform-overview";
import { settled } from "@/components/admin/settled";
import { adminConfig } from "@/lib/admin-config";
import { adminPage } from "@/lib/admin-page";

export const dynamic = "force-dynamic";

export default async function AdminOverviewPage() {
  await adminPage("admin.overview.viewed");
  const t = await getTranslations("admin-console.overview");

  const [product, platform, integrations] = await Promise.allSettled([
    (async () => (await adminConfig.overviewPanels?.()) ?? null)(),
    Promise.all([
      getPlatformOverview(),
      listWorkspaces(10),
      listUnsettledExecutions(),
    ]),
    getIntegrationHealth(),
  ]);

  return (
    <>
      <PageTitle title={t("title")} description={t("description")} />
      {settled(product, (panels) => panels, "admin-console.reads.product")}
      {settled(
        platform,
        ([overview, workspaces, unsettled]) => (
          <PlatformOverview
            overview={overview}
            workspaces={workspaces}
            unsettled={unsettled.length}
          />
        ),
        "admin-console.reads.platform"
      )}
      {settled(
        integrations,
        (value) => (
          <IntegrationHealth integrations={value} />
        ),
        "admin-console.reads.health"
      )}
    </>
  );
}

"use client";

/**
 * The admin console's error boundary, inside its own layout. Renders the
 * shared `RouteError` from the `route-error` item.
 */

import { RouteError } from "@/components/shared/route-error";

export default function AdminError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return (
    <RouteError
      error={error}
      reset={reset}
      scope="admin"
      homeHref="/admin"
      homeKey="goHome"
    />
  );
}

/**
 * Users and their workspaces, newest first, searchable by email, name or
 * workspace name and paged. A row opens the user in the panel beside the
 * list, with a link to each workspace's support page.
 */

import {
  getSignupsByDay,
  listUserSummaries,
  type UserSummary,
} from "@intelligo-dev/admin";
import { getTimeZone, getTranslations } from "next-intl/server";

import { DataList, type ListRow } from "@/components/admin/data-list";
import { PageTitle } from "@/components/admin/page-title";
import { Panel, Stat } from "@/components/admin/panel";
import { Properties, PropertySection } from "@/components/admin/properties";
import { settled } from "@/components/admin/settled";
import { Link } from "@/i18n/navigation";
import { adminFormat, type AdminFormat } from "@/lib/admin-format";
import { readListQuery, type ListSearchParams } from "@/lib/admin-list";
import { adminPage } from "@/lib/admin-page";
import { planName } from "@/lib/plan-copy";

export const dynamic = "force-dynamic";

type T = Awaited<ReturnType<typeof getTranslations>>;

export default async function AdminUsersPage({
  searchParams,
}: {
  searchParams: Promise<ListSearchParams>;
}) {
  await adminPage("admin.users.viewed");
  const query = readListQuery(await searchParams);
  const t = await getTranslations("admin-console.users");

  const [users, signups] = await Promise.allSettled([
    listUserSummaries({
      query: query.q || undefined,
      limit: query.size,
      offset: query.offset,
    }),
    getSignupsByDay({ days: 30, timeZone: await getTimeZone() }),
  ]);

  return (
    <>
      <PageTitle title={t("title")} description={t("description")} />
      {settled(
        signups,
        (days) => (
          <SignupStats days={days} />
        ),
        "admin-console.reads.signups"
      )}
      <Panel title={t("list")}>
        {settled(
          users,
          (page) => (
            <UserList rows={page.rows} total={page.total} query={query} />
          ),
          "admin-console.reads.users"
        )}
      </Panel>
    </>
  );
}

async function SignupStats({ days }: { days: { count: number }[] }) {
  const t = await getTranslations("admin-console.users.signups");
  const f = await adminFormat();
  const sum = (list: { count: number }[]) =>
    list.reduce((total, d) => total + d.count, 0);
  return (
    <div className="grid gap-3 sm:grid-cols-3">
      <Stat label={t("month")} value={f.number(sum(days))} />
      <Stat label={t("week")} value={f.number(sum(days.slice(-7)))} />
      <Stat label={t("today")} value={f.number(days.at(-1)?.count ?? 0)} />
    </div>
  );
}

async function UserList({
  rows,
  total,
  query,
}: {
  rows: UserSummary[];
  total: number;
  query: ReturnType<typeof readListQuery>;
}) {
  const t = await getTranslations("admin-console.users");
  const tPlans = await getTranslations("plans");
  const f = await adminFormat();
  const open = rows.find((u) => u.id === query.open) ?? null;
  const first = open?.workspaces[0];

  return (
    <DataList
      columns={[
        { key: "user", header: t("columns.user") },
        { key: "workspace", header: t("columns.workspace") },
        { key: "plan", header: t("columns.plan") },
        { key: "joined", header: t("columns.joined"), className: "text-right" },
      ]}
      rows={rows.map((u) => userRow(u, t, tPlans, f))}
      total={total}
      page={query.page}
      pageSize={query.size}
      search={query.q}
      searchPlaceholder={t("search")}
      openId={open?.id ?? null}
      panelTitle={open ? open.name || open.email : undefined}
      panelDescription={open?.name ? open.email : undefined}
      fullPageHref={first ? `/admin/users/${first.id}` : undefined}
      panel={open ? <UserPanel user={open} /> : undefined}
      empty={t("empty")}
    />
  );
}

function userRow(u: UserSummary, t: T, tPlans: T, f: AdminFormat): ListRow {
  const [first, ...more] = u.workspaces;
  return {
    id: u.id,
    cells: {
      user: {
        text: u.name ?? u.email,
        note: u.name ? u.email : undefined,
        badge: u.platformRole ? t("platformAdmin") : undefined,
        tone: "info",
      },
      workspace: first
        ? {
            text: first.name,
            note: more.length
              ? t("more", { role: first.role, count: more.length })
              : first.role,
          }
        : "",
      plan: first?.planSlug
        ? planName(tPlans, first.planSlug, first.planSlug)
        : "",
      joined: f.date(u.createdAt),
    },
  };
}

async function UserPanel({ user }: { user: UserSummary }) {
  const t = await getTranslations("admin-console.users.panel");
  const tPlans = await getTranslations("plans");
  const f = await adminFormat();
  return (
    <div className="flex flex-col gap-4">
      <Properties
        properties={[
          { key: "email", label: t("email"), value: user.email },
          { key: "name", label: t("name"), value: user.name },
          { key: "role", label: t("platformRole"), value: user.platformRole },
          {
            key: "joined",
            label: t("joined"),
            value: f.dateTime(user.createdAt),
          },
          { key: "id", label: t("id"), value: user.id, mono: true },
        ]}
      />
      <PropertySection title={t("workspaces")}>
        {user.workspaces.length === 0 ? (
          <p className="text-sm text-muted-foreground">{t("noWorkspaces")}</p>
        ) : (
          <ul className="divide-y text-sm">
            {user.workspaces.map((w) => (
              <li
                key={w.id}
                className="flex items-center justify-between gap-2 py-2"
              >
                <Link
                  href={`/admin/users/${w.id}`}
                  className="font-medium hover:underline"
                >
                  {w.name}
                </Link>
                <span className="text-xs text-muted-foreground">
                  {w.planSlug
                    ? t("roleOnPlan", {
                        role: w.role,
                        plan: planName(tPlans, w.planSlug, w.planSlug),
                      })
                    : w.role}
                </span>
              </li>
            ))}
          </ul>
        )}
      </PropertySection>
    </div>
  );
}

/**
 * One workspace, for support: its plan, credit and members, its payments
 * and recent executions — and the three things support may do about them:
 * grant a plan, add credit, act as a member. Each needs a reason and is
 * audited, or refused when the audit row cannot be written. The product's
 * own panels for the workspace follow (`adminConfig.workspacePanels`).
 */

import {
  getWorkspace,
  listPayments,
  listWorkspaceExecutions,
  listWorkspaceMembers,
} from "@intelligo-dev/admin";
import {
  getBillingSettings,
  getWorkspaceBilling,
} from "@intelligo-dev/billing";
import { notFound } from "next/navigation";
import { getTranslations } from "next-intl/server";

import { PageTitle } from "@/components/admin/page-title";
import { Panel, Stat } from "@/components/admin/panel";
import { settled } from "@/components/admin/settled";
import {
  ExecutionTable,
  MemberTable,
  PaymentTable,
} from "@/components/admin/workspace-tables";
import { SupportActions } from "@/components/admin/support-actions";
import { adminConfig } from "@/lib/admin-config";
import { adminFormat } from "@/lib/admin-format";
import { adminPage } from "@/lib/admin-page";
import { planName } from "@/lib/plan-copy";

export const dynamic = "force-dynamic";

export default async function AdminWorkspacePage({
  params,
}: {
  params: Promise<{ workspaceId: string }>;
}) {
  const { workspaceId } = await params;
  await adminPage("admin.workspace.viewed", {
    kind: "workspace",
    id: workspaceId,
    workspaceId,
  });
  const workspace = await getWorkspace(workspaceId);
  if (!workspace) notFound();

  const t = await getTranslations("admin-console.workspace");
  const f = await adminFormat();
  const [billing, members, payments, executions, settings, product] =
    await Promise.allSettled([
      getWorkspaceBilling(workspaceId),
      listWorkspaceMembers(workspaceId),
      listPayments({ workspaceId, limit: 20 }),
      listWorkspaceExecutions(workspaceId, 20),
      getBillingSettings(),
      (async () =>
        (await adminConfig.workspacePanels?.(workspaceId)) ?? null)(),
    ]);

  return (
    <>
      <PageTitle
        title={workspace.name}
        description={t("description", {
          slug: workspace.slug ?? workspace.id,
          created: f.date(workspace.createdAt),
        })}
        crumbs={[{ label: t("crumb"), href: "/admin/users" }]}
      />
      {settled(
        billing,
        (value) => (
          <BillingStats
            billing={value}
            members={
              members.status === "fulfilled" ? members.value.length : null
            }
          />
        ),
        "admin-console.reads.billing"
      )}
      {settled(
        settings,
        (value) => (
          <SupportActions
            workspaceId={workspaceId}
            currency={value.currency}
            members={members.status === "fulfilled" ? members.value : []}
          />
        ),
        "admin-console.reads.billingSettings"
      )}
      {settled(product, (panels) => panels, "admin-console.reads.product")}
      <Panel title={t("members.title")}>
        {settled(
          members,
          (rows) => (
            <MemberTable rows={rows} />
          ),
          "admin-console.reads.members"
        )}
      </Panel>
      <Panel title={t("payments.title")}>
        {settled(
          payments,
          (page) => (
            <PaymentTable rows={page.rows} />
          ),
          "admin-console.reads.payments"
        )}
      </Panel>
      <Panel title={t("executions.title")}>
        {settled(
          executions,
          (rows) => (
            <ExecutionTable rows={rows} />
          ),
          "admin-console.reads.executions"
        )}
      </Panel>
    </>
  );
}

async function BillingStats({
  billing,
  members,
}: {
  billing: Awaited<ReturnType<typeof getWorkspaceBilling>>;
  members: number | null;
}) {
  const t = await getTranslations("admin-console.workspace.stats");
  const tPlans = await getTranslations("plans");
  const f = await adminFormat();
  const { plan, subscription, creditBalance } = billing;
  const end = subscription?.currentPeriodEnd;
  return (
    <div className="grid gap-3 sm:grid-cols-3">
      <Stat
        label={t("plan")}
        value={plan ? planName(tPlans, plan.slug, plan.name) : t("noPlan")}
        hint={
          end
            ? t("until", { date: f.date(end) })
            : (subscription?.status ?? undefined)
        }
      />
      <Stat
        label={t("credit")}
        value={
          creditBalance.currency
            ? f.money({
                amount: creditBalance.balanceMicros,
                currency: creditBalance.currency,
              })
            : t("noCredit")
        }
      />
      <Stat
        label={t("members")}
        value={members === null ? "" : f.number(members)}
      />
    </div>
  );
}

/**
 * Money in and money out. The summary tab: the deployment's billing
 * settings, revenue per currency, what the models cost, plans in force,
 * and which models and users cost the most. The payments tab: the
 * local-payment ledger, paged. The ledger tab: every usage record, paged,
 * each checked against the rate it was charged at.
 */

import {
  countUsageRecords,
  getPlanDistribution,
  getProviderCostTotal,
  getRevenue,
  getUsageByModel,
  getUsageByUser,
  listPayments,
  listUsageRecords,
} from "@intelligo-dev/admin";
import { getBillingSettings } from "@intelligo-dev/billing";
import { getTranslations } from "next-intl/server";

import { UrlTabs } from "@/components/admin/data-list";
import { PageTitle } from "@/components/admin/page-title";
import { Panel } from "@/components/admin/panel";
import {
  BillingSettingsForm,
  RevenueStats,
  UsageTables,
} from "@/components/admin/revenue";
import { PaymentList, UsageLedger } from "@/components/admin/revenue-lists";
import { settled } from "@/components/admin/settled";
import { TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { readListQuery, type ListSearchParams } from "@/lib/admin-list";
import { adminPage } from "@/lib/admin-page";

export const dynamic = "force-dynamic";

const TABS = ["summary", "payments", "ledger"] as const;
type Tab = (typeof TABS)[number];

export default async function AdminRevenuePage({
  searchParams,
}: {
  searchParams: Promise<ListSearchParams>;
}) {
  await adminPage("admin.revenue.viewed");
  const params = await searchParams;
  const tab: Tab = TABS.find((name) => name === params.tab) ?? "summary";
  const t = await getTranslations("admin-console.revenue");

  return (
    <>
      <PageTitle title={t("title")} description={t("description")} />
      <UrlTabs initial="summary">
        <TabsList>
          {TABS.map((name) => (
            <TabsTrigger key={name} value={name}>
              {t(`tabs.${name}`)}
            </TabsTrigger>
          ))}
        </TabsList>
        <TabsContent value={tab} className="space-y-6 pt-4">
          {tab === "summary" && <Summary />}
          {tab === "payments" && <Payments params={params} />}
          {tab === "ledger" && <Ledger params={params} />}
        </TabsContent>
      </UrlTabs>
    </>
  );
}

async function Summary() {
  const t = await getTranslations("admin-console.revenue");
  const [settings, revenue, cost, plans, byModel, byUser] =
    await Promise.allSettled([
      getBillingSettings(),
      getRevenue(),
      getProviderCostTotal(),
      getPlanDistribution(),
      getUsageByModel(20),
      getUsageByUser(20),
    ]);
  return (
    <>
      <Panel title={t("settings.title")}>
        {settled(
          settings,
          (value) => (
            <BillingSettingsForm settings={value} />
          ),
          "admin-console.reads.billingSettings"
        )}
      </Panel>
      <RevenueStats revenue={revenue} cost={cost} plans={plans} />
      <UsageTables byModel={byModel} byUser={byUser} />
    </>
  );
}

async function Payments({ params }: { params: ListSearchParams }) {
  const query = readListQuery(params, { facets: ["status"] });
  const result = await listPayments({
    status: query.filters.status,
    limit: query.size,
    offset: query.offset,
  }).then(
    (value) => ({ status: "fulfilled" as const, value }),
    (reason: unknown) => ({ status: "rejected" as const, reason })
  );
  return settled(
    result,
    (page) => <PaymentList page={page} query={query} />,
    "admin-console.reads.payments"
  );
}

async function Ledger({ params }: { params: ListSearchParams }) {
  const query = readListQuery(params);
  const [records, total] = await Promise.allSettled([
    listUsageRecords(query.size, query.offset),
    countUsageRecords(),
  ]);
  return settled(
    records,
    (rows) => (
      <UsageLedger
        rows={rows}
        total={total.status === "fulfilled" ? total.value : rows.length}
        query={query}
      />
    ),
    "admin-console.reads.ledger"
  );
}

/**
 * What went wrong and who did what: jobs that exhausted their retries,
 * executions left unsettled (credit still held against them), and the
 * audit trail — filtered by action, paged, each event's actor and
 * resource named where they still resolve.
 */

import {
  countAuditEvents,
  listFailedJobs,
  listUnsettledExecutions,
  queryAuditEvents,
} from "@intelligo-dev/admin";
import { getTranslations } from "next-intl/server";

import { AuditList } from "@/components/admin/audit-list";
import { FailedJobs, UnsettledExecutions } from "@/components/admin/operations";
import { PageTitle } from "@/components/admin/page-title";
import { Panel } from "@/components/admin/panel";
import { settled } from "@/components/admin/settled";
import { readListQuery, type ListSearchParams } from "@/lib/admin-list";
import { adminPage } from "@/lib/admin-page";

export const dynamic = "force-dynamic";

export default async function AdminOperationsPage({
  searchParams,
}: {
  searchParams: Promise<ListSearchParams>;
}) {
  await adminPage("admin.operations.viewed");
  const query = readListQuery(await searchParams);
  const t = await getTranslations("admin-console.operations");
  const filter = query.q ? { action: query.q } : {};

  const [jobs, unsettled, events, total] = await Promise.allSettled([
    listFailedJobs(50),
    listUnsettledExecutions(),
    queryAuditEvents({ ...filter, limit: query.size, offset: query.offset }),
    countAuditEvents(filter),
  ]);

  return (
    <>
      <PageTitle title={t("title")} description={t("description")} />
      <div className="grid gap-4 lg:grid-cols-2">
        <Panel title={t("jobs.title")}>
          {settled(
            jobs,
            (rows) => (
              <FailedJobs rows={rows} />
            ),
            "admin-console.reads.jobs"
          )}
        </Panel>
        <Panel title={t("unsettled.title")}>
          {settled(
            unsettled,
            (rows) => (
              <UnsettledExecutions rows={rows} />
            ),
            "admin-console.reads.unsettled"
          )}
        </Panel>
      </div>
      <Panel title={t("audit.title")}>
        {settled(
          events,
          (rows) => (
            <AuditList
              rows={rows}
              total={total.status === "fulfilled" ? total.value : rows.length}
              query={query}
            />
          ),
          "admin-console.reads.audit"
        )}
      </Panel>
    </>
  );
}

"use server";

/**
 * The console's actions. Thin transports: parse, authorize with an audit
 * row or refuse (`requireAdminOrRefuse`), call the framework's service,
 * answer an `ActionResult` whose message is a key in
 * `admin-console.actions`, revalidate. The policy — who may act as whom,
 * how a plan grant ends, how credit is recorded, what a billing settings
 * change converts (nothing) — is the services'.
 *
 * A failure is answered with a key, never the error's own text, which can
 * carry internals; the error itself goes to the server log.
 */

import { requireAdminOrRefuse, startImpersonation } from "@intelligo-dev/admin";
import {
  creditWorkspace,
  getBillingSettings,
  grantPlan,
  updateBillingSettings,
} from "@intelligo-dev/billing";
import { createLogger } from "@intelligo-dev/core/logger";
import { fromMajor } from "@intelligo-dev/core/money";
import { revalidatePath } from "next/cache";
import { getFormatter, getLocale, getTranslations } from "next-intl/server";
import { z } from "zod";

import type { ActionResult } from "@/components/admin/action-form";
import { redirect } from "@/i18n/navigation";
import { adminConfig } from "@/lib/admin-config";
import { adminFormat } from "@/lib/admin-format";
import { composeIntelligo } from "@/lib/intelligo";
import { planName } from "@/lib/plan-copy";

const log = createLogger("admin-console");

const KEY = "admin-console.actions";

/** Error codes the services throw, and the message each is answered with. */
const ERRORS: Record<string, string> = {
  invalid_plan: "invalidPlan",
  invalid_currency: "invalidCurrency",
  invalid_rate: "invalidRate",
  invalid_margin: "invalidMargin",
  empty_update: "invalid",
  currency_mismatch: "currencyMismatch",
  invalid_amount: "invalid",
  forbidden: "refused",
  unauthenticated: "refused",
};

function failure(error: unknown, action: string): ActionResult {
  if (error instanceof z.ZodError) {
    const reason = error.issues.some((i) => i.path[0] === "reason");
    return {
      ok: false,
      message: `${KEY}.${reason ? "reasonRequired" : "invalid"}`,
    };
  }
  const code = (error as { code?: unknown } | null)?.code;
  const known = typeof code === "string" ? ERRORS[code] : undefined;
  if (known) return { ok: false, message: `${KEY}.${known}` };
  log.error("An admin action failed", {
    action,
    error:
      error instanceof Error ? (error.stack ?? error.message) : String(error),
  });
  return { ok: false, message: `${KEY}.failed` };
}

const done = (
  message: string,
  values?: Record<string, string>
): ActionResult => {
  revalidatePath("/[locale]/admin", "layout");
  return {
    ok: true,
    message: `${KEY}.${message}`,
    ...(values ? { values } : {}),
  };
};

const reason = z.string().trim().min(3);

const grantInput = z.object({
  workspaceId: z.string().min(1),
  planSlug: z.string().min(1),
  days: z.coerce.number().int().min(0).max(3650),
  reason,
});

export async function grantPlanAction(
  _prev: ActionResult,
  formData: FormData
): Promise<ActionResult> {
  composeIntelligo();
  try {
    const input = grantInput.parse(Object.fromEntries(formData));
    const actor = await requireAdminOrRefuse(
      "admin.plan.granted",
      {
        kind: "workspace",
        id: input.workspaceId,
        workspaceId: input.workspaceId,
      },
      { planSlug: input.planSlug, days: input.days, reason: input.reason }
    );
    const result = await grantPlan({
      workspaceId: input.workspaceId,
      planSlug: input.planSlug,
      reason: input.reason,
      actorId: actor.userId,
      ...(input.days > 0 ? { days: input.days } : { endsAt: null }),
    });
    const f = await adminFormat();
    const plan = planName(
      await getTranslations("plans"),
      input.planSlug,
      input.planSlug
    );
    return result.endsAt
      ? done("planGranted", { plan, endsAt: f.date(result.endsAt) })
      : done("planGrantedOpen", { plan });
  } catch (error) {
    return failure(error, "grantPlan");
  }
}

const creditInput = z.object({
  workspaceId: z.string().min(1),
  amount: z.coerce.number().positive().max(1_000_000_000),
  reason,
  /** Minted when the form renders, so a resubmitted form is the same request, credited once. */
  requestId: z.uuid(),
});

export async function creditAction(
  _prev: ActionResult,
  formData: FormData
): Promise<ActionResult> {
  composeIntelligo();
  try {
    const input = creditInput.parse(Object.fromEntries(formData));
    const actor = await requireAdminOrRefuse(
      "admin.credit.granted",
      {
        kind: "workspace",
        id: input.workspaceId,
        workspaceId: input.workspaceId,
      },
      { amount: input.amount, reason: input.reason }
    );
    // Credit is added in what the deployment bills in, never a currency the form names.
    const { currency } = await getBillingSettings();
    const amount = fromMajor(input.amount, currency);
    const { replayed } = await creditWorkspace(input.workspaceId, amount, {
      reason: input.reason,
      requestId: `admin-credit:${input.requestId}`,
      actorId: actor.userId,
    });
    if (replayed) return done("creditReplayed");
    const f = await adminFormat();
    return done("creditAdded", { amount: f.money(amount) });
  } catch (error) {
    return failure(error, "credit");
  }
}

const impersonateInput = z.object({
  userId: z.string().min(1),
  reason,
});

export async function impersonateAction(
  _prev: ActionResult,
  formData: FormData
): Promise<ActionResult> {
  composeIntelligo();
  try {
    const { userId, reason } = impersonateInput.parse(
      Object.fromEntries(formData)
    );
    const result = await startImpersonation({ targetUserId: userId, reason });
    log.warn("Impersonation started", {
      targetUserId: userId,
      expiresAt: result.expiresAt.toISOString(),
    });
  } catch (error) {
    if (error instanceof z.ZodError) return failure(error, "impersonate");
    // Not surfaced: why it failed (not an admin, the target is one, the
    // audit row could not be written) is what a caller who should not be
    // here would want to learn.
    log.error("Impersonation refused", {
      error: error instanceof Error ? error.message : String(error),
    });
    return { ok: false, message: `${KEY}.impersonationFailed` };
  }
  // Outside the try: redirect() signals by throwing.
  redirect({ href: adminConfig.backHref, locale: await getLocale() });
  return null;
}

const settingsInput = z.object({
  currency: z.string().trim().toUpperCase().length(3),
  usdRate: z.coerce.number().positive(),
  marginPercent: z.coerce.number().int().positive().max(100_000),
});

export async function updateBillingSettingsAction(
  _prev: ActionResult,
  formData: FormData
): Promise<ActionResult> {
  composeIntelligo();
  try {
    const input = settingsInput.parse(Object.fromEntries(formData));
    await requireAdminOrRefuse(
      "admin.billing_settings.updated",
      { kind: "billing_settings", id: "default" },
      { ...input }
    );
    await updateBillingSettings({
      currency: input.currency,
      // What one USD costs, as an amount of the new currency.
      usdRateMicros: fromMajor(input.usdRate, input.currency).amount,
      marginBp: input.marginPercent * 100,
    });
    const format = await getFormatter();
    return done("settingsSaved", {
      currency: input.currency,
      rate: format.number(input.usdRate),
    });
  } catch (error) {
    return failure(error, "updateBillingSettings");
  }
}

