/** A status's tone: done is success, a refusal or lapse a warning, a failure destructive. */
export type Tone = "neutral" | "info" | "success" | "warning" | "destructive";

const TONES: Record<string, Tone> = {
  ok: "success",
  paid: "success",
  succeeded: "success",
  active: "success",
  running: "info",
  settling: "info",
  pending: "info",
  opening: "info",
  degraded: "warning",
  refused: "warning",
  expired: "warning",
  cancelled: "warning",
  canceled: "warning",
  past_due: "warning",
  unconfigured: "neutral",
  down: "destructive",
  failed: "destructive",
  failure: "destructive",
};

/** The tone a status word reads in; `neutral` for one the console does not know. */
export function toneOf(status: string): Tone {
  return TONES[status] ?? "neutral";
}

/**
 * A payment's, execution's, job's or probe's status, in the reader's
 * words when `admin-console.status` has them and as stored otherwise.
 */
export function Status({ status }: { status: string }) {
  const t = useTranslations("admin-console.status");
  return (
    <StatusBadge status={toneOf(status)}>
      {t.has(status) ? t(status) : status}
    </StatusBadge>
  );
}

/** A payment's status, flagged when it was paid but its plan or credit was never granted. */
export function PaymentStatus({
  status,
  fulfilledAt,
}: {
  status: string;
  fulfilledAt: Date | null;
}) {
  const t = useTranslations("admin-console.status");
  return (
    <span className="inline-flex flex-wrap gap-1">
      <Status status={status} />
      {status === "paid" && !fulfilledAt && (
        <StatusBadge status="destructive">{t("notGranted")}</StatusBadge>
      )}
    </span>
  );
}

import "server-only";

/**
 * One read of a console page, rendered on its own: a read that failed
 * says so in its place and goes to the server log, and the rest of the
 * page still renders — the console exists to be readable while things
 * are broken.
 *
 * A page starts its reads with `Promise.allSettled` and hands each
 * result to `settled` with what it was, as a key in the `admin-console`
 * namespace's `reads` (or any fully-qualified key the product owns).
 */

import { createLogger } from "@intelligo-dev/core/logger";
import { useTranslations } from "next-intl";
import type { ReactNode } from "react";

const log = createLogger("admin-console");

/** In place of a read that failed. */
export function Unavailable({ what }: { what: string }) {
  const t = useTranslations();
  const name = t.has(what) ? t(what) : what;
  return (
    <p className="text-sm text-muted-foreground">
      {t("admin-console.unavailable", { what: name })}
    </p>
  );
}

export function settled<T>(
  result: PromiseSettledResult<T>,
  render: (value: T) => ReactNode,
  what: string
): ReactNode {
  if (result.status === "fulfilled") return render(result.value);
  const reason: unknown = result.reason;
  log.error("An admin read failed", {
    what,
    error:
      reason instanceof Error
        ? (reason.stack ?? reason.message)
        : String(reason),
  });
  return <Unavailable what={what} />;
}

"use client";

/**
 * A form bound to a console server action. The action answers an
 * `ActionResult`: whether it worked and a fully-qualified message key,
 * with the values the message names. The answer shows as a toast, a
 * failure also under the form, and the page refreshes on success so the
 * change is visible.
 */

import { useTranslations } from "next-intl";
import { useActionState, useEffect, type ReactNode } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { FieldError, FieldLabel } from "@/components/ui/field";
import { useRouter } from "@/i18n/navigation";

export type ActionResult = {
  ok: boolean;
  /** A fully-qualified message key, e.g. `admin-console.actions.planGranted`. */
  message: string;
  values?: Record<string, string | number | Date>;
} | null;

export interface ActionFormProps {
  action: (prev: ActionResult, formData: FormData) => Promise<ActionResult>;
  /** The submit button's label. */
  submit: string;
  children?: ReactNode;
  variant?: "default" | "outline" | "destructive";
}

export function ActionForm({
  action,
  submit,
  children,
  variant = "default",
}: ActionFormProps) {
  const t = useTranslations();
  const router = useRouter();
  const [state, formAction, pending] = useActionState(action, null);
  const text = state ? t(state.message, state.values) : "";

  useEffect(() => {
    if (!state) return;
    if (state.ok) {
      toast.success(text);
      router.refresh();
    } else toast.error(text);
  }, [state, text, router]);

  return (
    <form action={formAction} className="grid gap-2">
      {children}
      <Button
        type="submit"
        size="sm"
        variant={variant}
        disabled={pending}
        className="w-fit"
      >
        {submit}
      </Button>
      {state && !state.ok && (
        <FieldError className="text-xs">{text}</FieldError>
      )}
    </form>
  );
}

/** A labelled control; the label wraps it, so the control needs no id. */
export function Field({
  label,
  children,
}: {
  label: string;
  children: ReactNode;
}) {
  return (
    <FieldLabel className="w-full flex-col items-stretch gap-1.5">
      <span className="text-xs font-normal text-muted-foreground">{label}</span>
      {children}
    </FieldLabel>
  );
}

/** A native `<select>` (it posts with the form, no client state) dressed as the registry `Input`. */
