"use client";

/**
 * The admin console's sidebar: the registry's AISidebar, as the app
 * shell's, so it collapses to an icon rail and becomes a drawer on a
 * phone. Entries come from `@/lib/admin-nav` (consumer config); each
 * `titleKey` is a fully-qualified message key, resolved through a
 * namespace-less `useTranslations()`.
 *
 * The most specific entry wins the highlight: `/admin/users/ws_1` lights
 * "Users", never "Overview". A group stands open while one of its pages
 * is shown, unless the reader folded it.
 */

import { ArrowLeft } from "lucide-react";
import { useTranslations } from "next-intl";
import { useState } from "react";

import {
  AISidebar,
  AISidebarContent,
  AISidebarFooter,
  AISidebarHeader,
  AISidebarItem,
  AISidebarMenu,
  AISidebarMenuItem,
  AISidebarRail,
  AISidebarSection,
  AISidebarSubItem,
  AISidebarSubmenu,
} from "@/components/ui/ai-sidebar";
import { Link, usePathname } from "@/i18n/navigation";
import { adminNav, type AdminNavItem } from "@/lib/admin-nav";

const PAGES = adminNav.flatMap((item) => item.children ?? [item]);

/** The href of the entry the current path belongs to most specifically. */
function activeHref(pathname: string): string | undefined {
  const matches = (href: string) =>
    href === "/admin"
      ? pathname === href
      : pathname === href || pathname.startsWith(`${href}/`);
  return PAGES.filter((item) => matches(item.href)).sort(
    (a, b) => b.href.length - a.href.length
  )[0]?.href;
}

export interface AdminSidebarProps {
  /** The name at the top, already translated by the layout. */
  brand: string;
  /** Where "Back to the app" goes. */
  backHref: string;
}

export function AdminSidebar({ brand, backHref }: AdminSidebarProps) {
  const t = useTranslations();
  const best = activeHref(usePathname());
  const [folded, setFolded] = useState<Record<string, boolean>>({});

  return (
    <AISidebar
      collapsible="icon"
      label={t("admin-console.nav.label")}
      closeLabel={t("admin-console.nav.close")}
    >
      <AISidebarHeader>
        <div className="truncate px-2 py-1 text-sm font-semibold group-data-[state=collapsed]/sidebar:hidden">
          {brand}
        </div>
      </AISidebarHeader>
      <AISidebarContent>
        <AISidebarSection>
          <AISidebarMenu>
            {adminNav.map((item) => (
              <NavEntry
                key={item.href}
                item={item}
                best={best}
                folded={folded[item.href]}
                onFold={(open) =>
                  setFolded((f) => ({ ...f, [item.href]: open }))
                }
              />
            ))}
          </AISidebarMenu>
        </AISidebarSection>
      </AISidebarContent>
      <AISidebarFooter>
        <AISidebarMenu>
          <AISidebarMenuItem>
            <AISidebarItem
              icon={<ArrowLeft />}
              tooltip={t("admin-console.nav.backToApp")}
              render={<Link href={backHref} />}
            >
              {t("admin-console.nav.backToApp")}
            </AISidebarItem>
          </AISidebarMenuItem>
        </AISidebarMenu>
      </AISidebarFooter>
      <AISidebarRail label={t("admin-console.nav.toggle")} />
    </AISidebar>
  );
}

function NavEntry({
  item,
  best,
  folded,
  onFold,
}: {
  item: AdminNavItem;
  best: string | undefined;
  folded: boolean | undefined;
  onFold: (open: boolean) => void;
}) {
  const t = useTranslations();
  const { href, titleKey, icon: Icon, children } = item;
  const label = t(titleKey);

  if (!children) {
    return (
      <AISidebarMenuItem>
        <AISidebarItem
          isActive={href === best}
          icon={<Icon />}
          tooltip={label}
          render={<Link href={href} />}
        >
          {label}
        </AISidebarItem>
      </AISidebarMenuItem>
    );
  }

  const inside = children.some((child) => child.href === best);
  const open = folded === undefined ? inside : !folded;
  return (
    <AISidebarMenuItem>
      <AISidebarItem
        isActive={inside && !open}
        icon={<Icon />}
        tooltip={label}
        expanded={open}
        onSelect={() => onFold(open)}
      >
        {label}
      </AISidebarItem>
      <AISidebarSubmenu open={open}>
        {children.map((child) => (
          <AISidebarSubItem
            key={child.href}
            isActive={child.href === best}
            icon={<child.icon />}
            render={<Link href={child.href} />}
          >
            {t(child.titleKey)}
          </AISidebarSubItem>
        ))}
      </AISidebarSubmenu>
    </AISidebarMenuItem>
  );
}

"use client";

/**
 * A console list: the registry's DataTable with its toolbar, filter chips
 * and pagination, and the RecordPanel beside it. Its state lives in the
 * URL (`q`, `page`, `size`, `sort`, `order`, one parameter per facet,
 * `open` for the row in the panel), so the server page re-reads the same
 * query, renders the rows and — when a row is open — the panel's body,
 * and a list can be linked to as it stands.
 *
 * Rows cross the server boundary as plain cells (text, a badge, a note
 * under it), never as render functions; the server writes dates, numbers
 * and money into them already formatted. Copy comes from the
 * `admin-console` namespace's `list`, `panel` and `properties` keys.
 */

import { useSearchParams } from "next/navigation";
import { useTranslations } from "next-intl";
import {
  useCallback,
  useMemo,
  useState,
  useTransition,
  type ReactNode,
} from "react";

import {
  DataTable,
  DataTableFilterChips,
  DataTablePagination,
  DataTableToolbar,
  type DataTableColumn,
  type DataTableFacet,
  type DataTableLabels,
} from "@/components/ui/data-table";
import type { PropertyListLabels } from "@/components/ui/property-list";
import {
  RecordPanel,
  type RecordPanelLabels,
} from "@/components/ui/record-panel";
import { Spinner } from "@/components/ui/spinner";
import { StatusBadge } from "@/components/ui/status-badge";
import { Tabs } from "@/components/ui/tabs";
import { Link, usePathname, useRouter } from "@/i18n/navigation";
import type { Tone } from "@/components/admin/panel";

export type { Tone };

/** The data table's copy, in the reader's language. */
export function useTableLabels(): Partial<DataTableLabels> {
  const t = useTranslations("admin-console.list");
  return useMemo(
    () => ({
      search: t("search"),
      noResults: t("noResults"),
      rowsPerPage: t("rowsPerPage"),
      previousPage: t("previousPage"),
      nextPage: t("nextPage"),
      pageOf: (page: number, pages: number) => t("pageOf", { page, pages }),
      results: (total: number) => t("results", { total }),
      columns: t("columns"),
      density: t("density"),
      compact: t("compact"),
      comfortable: t("comfortable"),
      sortAscending: t("sortAscending"),
      sortDescending: t("sortDescending"),
      hideColumn: t("hideColumn"),
      selectAll: t("selectAll"),
      selectRow: t("selectRow"),
      actions: t("actions"),
      filters: t("filters"),
      clear: t("clear"),
      reset: t("reset"),
      noOptions: t("noOptions"),
    }),
    [t]
  );
}

/** The record panel's copy, in the reader's language. */
export function usePanelLabels(): Partial<RecordPanelLabels> {
  const t = useTranslations("admin-console.panel");
  return useMemo(
    () => ({
      previous: t("previous"),
      next: t("next"),
      fullPage: t("fullPage"),
    }),
    [t]
  );
}

/** The property list's copy, in the reader's language. */
export function usePropertyLabels(): Partial<PropertyListLabels> {
  const t = useTranslations("admin-console.properties");
  return useMemo(
    () => ({
      empty: t("empty"),
      yes: t("yes"),
      no: t("no"),
      showEmpty: (count: number) => t("showEmpty", { count }),
      hideEmpty: t("hideEmpty"),
    }),
    [t]
  );
}

export interface ListColumn {
  key: string;
  header: string;
  sortKey?: string;
  className?: string;
}

export type ListCell =
  | string
  | {
      text: string;
      /** A word in a badge after the text: the row's state, in its tone. */
      badge?: string;
      tone?: Tone;
      /** A second, muted line. */
      note?: string;
      mono?: boolean;
    };

export interface ListRow {
  id: string;
  cells: Record<string, ListCell>;
}

/** The URL as the list's state: every change is a navigation the server page answers. */
export function useListParams() {
  const router = useRouter();
  const pathname = usePathname();
  const params = useSearchParams();
  const [pending, startTransition] = useTransition();
  const set = useCallback(
    (patch: Record<string, string | null>) => {
      const next = new URLSearchParams(params.toString());
      for (const [key, value] of Object.entries(patch)) {
        if (value === null || value === "") next.delete(key);
        else next.set(key, value);
      }
      const query = next.toString();
      startTransition(() =>
        router.replace(query ? `${pathname}?${query}` : pathname, {
          scroll: false,
        })
      );
    },
    [params, pathname, router]
  );
  return { params, set, pending };
}

/**
 * Tabs whose choice is the URL's `?tab=`, so a tab can be linked to and
 * survives a refresh. Changing tab starts its list on the first page with
 * no row open.
 */
export function UrlTabs({
  initial,
  children,
}: {
  initial: string;
  children: ReactNode;
}) {
  const { params, set } = useListParams();
  return (
    <Tabs
      value={params.get("tab") ?? initial}
      onValueChange={(tab) => set({ tab: String(tab), page: null, open: null })}
    >
      {children}
    </Tabs>
  );
}

function Cell({ cell }: { cell: ListCell | undefined }) {
  if (cell === undefined || cell === "")
    return <span className="text-muted-foreground">—</span>;
  if (typeof cell === "string")
    return <span className="whitespace-normal">{cell}</span>;
  return (
    <div className="flex min-w-0 flex-col gap-0.5 whitespace-normal">
