import "server-only";

/**
 * The audit trail as a console list: newest first, filtered by action
 * (the search box takes an exact action name), paged. An event's actor,
 * its workspace and — for a user or workspace resource — the resource are
 * shown by name where they still resolve, by the recorded email or id
 * otherwise. A row opens the whole event, metadata included.
 */

import {
  resolveDisplayNames,
  type DisplayNames,
  type queryAuditEvents,
} from "@intelligo-dev/admin";
import { getTranslations } from "next-intl/server";

import { DataList, type ListRow } from "@/components/admin/data-list";
import { toneOf } from "@/components/admin/panel";
import { Properties } from "@/components/admin/properties";
import { adminConfig } from "@/lib/admin-config";
import { adminFormat, type AdminFormat } from "@/lib/admin-format";
import type { ListQuery } from "@/lib/admin-list";

type AuditEvent = Awaited<ReturnType<typeof queryAuditEvents>>[number];
type T = Awaited<ReturnType<typeof getTranslations>>;

/** `user`, `system` or `support`, in the reader's words when the messages have them. */
function kindOf(e: AuditEvent, t: T): string {
  const key = `actorKinds.${e.actorKind}`;
  return t.has(key) ? t(key) : e.actorKind;
}

function actorOf(e: AuditEvent, names: DisplayNames, t: T): string {
  const user = e.actorId ? names.users[e.actorId] : undefined;
  if (user) return user.name ?? user.email;
  return e.actorEmail ?? kindOf(e, t);
}

function resourceOf(e: AuditEvent, names: DisplayNames): string {
  const id = e.resourceId;
  if (!id) return e.resourceKind;
  const named =
    e.resourceKind === "workspace"
      ? names.workspaces[id]
      : e.resourceKind === "user"
        ? (names.users[id]?.name ?? names.users[id]?.email)
        : undefined;
  return named ?? id;
}

async function namesFor(rows: AuditEvent[]): Promise<DisplayNames> {
  const ids = (kind: string) =>
    rows.flatMap((e) =>
      e.resourceKind === kind && e.resourceId ? [e.resourceId] : []
    );
  return resolveDisplayNames({
    userIds: [
      ...rows.flatMap((e) => (e.actorId ? [e.actorId] : [])),
      ...ids("user"),
    ],
    workspaceIds: [
      ...rows.flatMap((e) => (e.workspaceId ? [e.workspaceId] : [])),
      ...ids("workspace"),
    ],
  });
}

function auditRow(
  e: AuditEvent,
  names: DisplayNames,
  t: T,
  f: AdminFormat,
  tStatus: T
): ListRow {
  return {
    id: e.id,
    cells: {
      date: f.dateTime(e.createdAt),
      action: { text: e.action, mono: true },
      resource: { text: resourceOf(e, names), note: e.resourceKind },
      workspace: e.workspaceId
        ? (names.workspaces[e.workspaceId] ?? e.workspaceId)
        : "",
      actor: { text: actorOf(e, names, t), note: kindOf(e, t) },
      outcome: {
        text: "",
        badge: tStatus.has(e.outcome) ? tStatus(e.outcome) : e.outcome,
        tone: toneOf(e.outcome),
      },
    },
  };
}

export async function AuditList({
  rows,
  total,
  query,
}: {
  rows: AuditEvent[];
  total: number;
  query: ListQuery;
}) {
  const t = await getTranslations("admin-console.operations.audit");
  const tAll = await getTranslations();
  const tStatus = await getTranslations("admin-console.status");
  const f = await adminFormat();
  const names = await namesFor(rows);
  const open = rows.find((e) => e.id === query.open) ?? null;

  return (
    <DataList
      columns={[
        { key: "date", header: t("date") },
        { key: "action", header: t("action") },
        { key: "resource", header: t("resource") },
        { key: "workspace", header: t("workspace") },
        { key: "actor", header: t("actor") },
        { key: "outcome", header: t("outcome") },
      ]}
      rows={rows.map((e) => auditRow(e, names, t, f, tStatus))}
      total={total}
      page={query.page}
      pageSize={query.size}
      search={query.q}
      searchPlaceholder={tAll(adminConfig.auditFilterPlaceholderKey)}
      openId={open?.id ?? null}
      panelTitle={open?.action}
      panelDescription={open ? f.dateTime(open.createdAt) : undefined}
      fullPageHref={
        open?.workspaceId ? `/admin/users/${open.workspaceId}` : undefined
      }
      panel={
        open ? (
          <Properties
            properties={[
              {
                key: "actor",
                label: t("actor"),
                value: actorOf(open, names, t),
              },
              {
                key: "actorKind",
                label: t("actorKind"),
                value: kindOf(open, t),
              },
              {
                key: "resource",
                label: t("resource"),
                value: resourceOf(open, names),
              },
              {
                key: "resourceKind",
                label: t("resourceKind"),
                value: open.resourceKind,
              },
              {
                key: "resourceId",
                label: t("resourceId"),
                value: open.resourceId,
                mono: true,
              },
              {
                key: "workspace",
                label: t("workspace"),
                value: open.workspaceId
                  ? (names.workspaces[open.workspaceId] ?? open.workspaceId)
                  : null,
              },
              { key: "outcome", label: t("outcome"), value: open.outcome },
              { key: "metadata", label: t("metadata"), value: open.metadata },
              { key: "id", label: t("id"), value: open.id, mono: true },
            ]}
          />
        ) : undefined
      }
      empty={t("empty")}
    />
  );
}

/**
 * The admin console's sidebar — consumer-owned (the contract of
 * `lib/settings-nav.ts` for the settings tabs).
 *
 * `components/admin/admin-sidebar.tsx` renders exactly this list, in this
 * order. Add the product's own console pages (`{ titleKey:
 * "admin.nav.content", href: "/admin/content", icon: Newspaper }`), group
 * several under one entry with `children`, or remove a section — no
 * component edit needed.
 *
 * `titleKey` is a fully-qualified message key resolved through a
 * namespace-less `useTranslations()`: the defaults point into this item's
 * `admin-console` namespace, and an entry you add can point into any
 * namespace you own.
 *
 * Icons are Lucide components, so this file is imported by the client
 * sidebar and never passed from a server layout: component values cannot
 * cross the RSC boundary as props.
 */

import { Activity, Gauge, Users, Wallet, type LucideIcon } from "lucide-react";

export interface AdminNavItem {
  /** Fully-qualified message key for the label. */
  titleKey: string;
  /** Locale-less href; `@/i18n/navigation`'s Link localizes it. */
  href: string;
  icon: LucideIcon;
  /** A group: the entry opens these instead of a page of its own. */
  children?: readonly AdminNavItem[];
}

export const adminNav: readonly AdminNavItem[] = [
  { titleKey: "admin-console.nav.overview", href: "/admin", icon: Gauge },
  { titleKey: "admin-console.nav.users", href: "/admin/users", icon: Users },
  {
    titleKey: "admin-console.nav.revenue",
    href: "/admin/revenue",
    icon: Wallet,
  },
  {
    titleKey: "admin-console.nav.operations",
    href: "/admin/operations",
    icon: Activity,
  },
];

/**
 * The admin console's product slots — consumer-owned, server-side (the
 * console's pages import it; no client component does, so a slot may
 * read the database).
 *
 * - `brandKey`: the fully-qualified message key of the name at the top of
 *   the sidebar.
 * - `backHref`: where "Back to the app" goes.
 * - `overviewPanels`: the product's own panels, rendered first on the
 *   overview, above the platform's (the work waiting for review, the
 *   numbers the product is run by).
 * - `workspacePanels(workspaceId)`: the product's own panels on a
 *   workspace's support page, under its stats and support actions.
 * - `auditFilterPlaceholderKey`: the message key of the hint in the
 *   operations page's audit filter — an action name the product records.
 *
 * A slot is called on the server for each request and may be async. One
 * that throws is reported as unreadable in its place; the rest of the page
 * still renders. Its copy belongs in a message namespace of the product's.
 */

import type { ReactNode } from "react";

export interface AdminConfig {
  brandKey: string;
  backHref: string;
  overviewPanels?: () => ReactNode | Promise<ReactNode>;
  workspacePanels?: (workspaceId: string) => ReactNode | Promise<ReactNode>;
  auditFilterPlaceholderKey: string;
}

export const adminConfig: AdminConfig = {
  brandKey: "admin-console.brand",
  backHref: "/dashboard",
  auditFilterPlaceholderKey: "admin-console.operations.audit.filter",
};

import "server-only";

/**
 * The console's gates, for its pages and for a product's own pages under
 * `/admin`.
 *
 * `adminPage(action, resource?)` composes the framework, then requires a
 * platform admin and records the visit (`requireAdmin`), or answers 404:
 * a "not authorized" page would say the route exists. A layout does not
 * guard a page's reads or its server actions, so every page calls this
 * itself, and every action authorizes with `requireAdminOrRefuse`.
 *
 * `adminLayoutGate()` is the layout's check: the same 404, with no audit
 * row, so a visit is recorded once — by the page.
 *
 * Anything other than "not an admin" (the database is down) is thrown to
 * the console's error boundary rather than hidden behind the 404.
 */

import { notFound } from "next/navigation";

import {
  isPlatformAdmin,
  requireAdmin,
  type AdminActor,
} from "@intelligo-dev/admin";
import { isAuthGuardError } from "@intelligo-dev/auth";

import { composeIntelligo } from "@/lib/intelligo";

export async function adminPage(
  action: string,
  resource?: { kind: string; id?: string; workspaceId?: string }
): Promise<AdminActor> {
  composeIntelligo();
  try {
    return await requireAdmin(action, resource);
  } catch (error) {
    if (isAuthGuardError(error)) notFound();
    throw error;
  }
}

export async function adminLayoutGate(): Promise<void> {
  composeIntelligo();
  if (!(await isPlatformAdmin())) notFound();
}

import "server-only";

/**
 * How the console writes dates, numbers and money: next-intl's formatter
 * for the request, so dates read in the reader's time zone (the `tz`
 * cookie the shell writes, through `i18n/request.ts`) and in their
 * locale. The pages format on the server and hand the client plain
 * strings, so the browser's `Intl` never re-formats a value the server
 * already wrote — the two can disagree, and the page would hydrate with
 * different text than it rendered.
 */

import { getFormatter } from "next-intl/server";

import { formatMoney, type MoneyLike } from "@/lib/format-money";

export type AdminFormat = {
  /** A calendar date, or "" for none. */
  date: (value: Date | null | undefined) => string;
  /** A date and time of day, or "" for none. */
  dateTime: (value: Date | null | undefined) => string;
  number: (value: number) => string;
  money: (value: MoneyLike) => string;
  /** Several amounts in different currencies, never summed together. */
  moneyList: (values: readonly MoneyLike[]) => string;
};

export async function adminFormat(): Promise<AdminFormat> {
  const format = await getFormatter();
  const money = (value: MoneyLike) => formatMoney(format, value);
  return {
    date: (value) =>
      value ? format.dateTime(value, { dateStyle: "medium" }) : "",
    dateTime: (value) =>
      value
        ? format.dateTime(value, { dateStyle: "medium", timeStyle: "short" })
        : "",
    number: (value) => format.number(value),
    money,
    moneyList: (values) => values.map(money).join(" · "),
  };
}

/**
 * A console list's state, read back from the URL `DataList` writes: the
 * search, the page and its size, the sort, the facets' chosen values and
 * the row open in the panel. Pure, so a server page and a test read it
 * the same way; anything malformed falls back to the first page.
 */

export type ListSearchParams = Record<string, string | string[] | undefined>;

export interface ListQuery {
  q: string;
  /** 1-based. */
  page: number;
  size: number;
  /** Rows before this page: `(page - 1) * size`. */
  offset: number;
  sort: string | null;
  order: "asc" | "desc";
  /** Each facet's chosen values, by facet key. */
  filters: Record<string, string[]>;
  open: string | null;
}

/** The page sizes `DataTablePagination` offers. */
export const PAGE_SIZES = [25, 50, 100] as const;

const one = (value: string | string[] | undefined): string =>
  (Array.isArray(value) ? value[0] : value)?.trim() ?? "";

export function readListQuery(
  params: ListSearchParams,
  options: { facets?: readonly string[]; sorts?: readonly string[] } = {}
): ListQuery {
  const asked = Number(one(params.size));
  const size = (PAGE_SIZES as readonly number[]).includes(asked)
    ? asked
    : PAGE_SIZES[0];
  const page = Math.max(1, Math.floor(Number(one(params.page)) || 1));
  const sort = one(params.sort);
  const filters: Record<string, string[]> = {};
  for (const key of options.facets ?? []) {
    const values = one(params[key]).split(",").filter(Boolean);
    if (values.length > 0) filters[key] = values;
  }
  return {
    q: one(params.q),
    page,
    size,
    offset: (page - 1) * size,
    sort: sort && options.sorts?.includes(sort) ? sort : null,
    order: one(params.order) === "desc" ? "desc" : "asc",
    filters,
    open: one(params.open) || null,
  };
}
